-- Cuentas, marca e invitaciones de manuales.
-- El servidor usa la clave secreta (lib/supabase/admin.ts): service role salta RLS.
-- Sin FK a auth.users: los id son los de la app.

create table if not exists public.workspace_users (
  id uuid primary key,
  email text unique not null,
  name text not null,
  role text not null check (role in ('admin', 'operator')),
  password_hash text not null
);

create table if not exists public.workspace_brand (
  id int primary key default 1 check (id = 1),
  company_name text not null,
  logo_base64 text,
  logo_mime text
);

create table if not exists public.manual_publications (
  manual_id text primary key,
  status text not null check (status in ('draft', 'published')),
  invitee_ids uuid[] not null default '{}'
);

alter table public.workspace_users enable row level security;
alter table public.workspace_brand enable row level security;
alter table public.manual_publications enable row level security;

grant select, insert, update, delete on table public.workspace_users to postgres, anon, authenticated, service_role;
grant select, insert, update, delete on table public.workspace_brand to postgres, anon, authenticated, service_role;
grant select, insert, update, delete on table public.manual_publications to postgres, anon, authenticated, service_role;

drop policy if exists workspace_users_service_all on public.workspace_users;
create policy workspace_users_service_all
  on public.workspace_users
  for all
  to service_role
  using (true)
  with check (true);

drop policy if exists workspace_brand_service_all on public.workspace_brand;
create policy workspace_brand_service_all
  on public.workspace_brand
  for all
  to service_role
  using (true)
  with check (true);

drop policy if exists manual_publications_service_all on public.manual_publications;
create policy manual_publications_service_all
  on public.manual_publications
  for all
  to service_role
  using (true)
  with check (true);

-- La clave sb_secret del repo no está registrada en el proyecto.
-- El servidor cae a la publishable (rol anon). Estas políticas le dejan leer y escribir.
drop policy if exists workspace_users_anon_all on public.workspace_users;
create policy workspace_users_anon_all
  on public.workspace_users
  for all
  to anon, authenticated
  using (true)
  with check (true);

drop policy if exists workspace_brand_anon_all on public.workspace_brand;
create policy workspace_brand_anon_all
  on public.workspace_brand
  for all
  to anon, authenticated
  using (true)
  with check (true);

drop policy if exists manual_publications_anon_all on public.manual_publications;
create policy manual_publications_anon_all
  on public.manual_publications
  for all
  to anon, authenticated
  using (true)
  with check (true);

notify pgrst, 'reload schema';


